import"./chunk-7CGTOI24.js";var e={common:{skip:"Skip to content",language:"Language",demoSession:"Demo session",restore:"Restore demo data",restoreTitle:"Restore the demo data?",restoreText:"Accounts, playlists, transfers and syncs go back to the initial state. Whatever you created in this demo is removed from this browser.",restored:"Demo data restored.",signOut:"Sign out",loading:"Loading...",back:"Back",next:"Next",cancel:"Cancel",close:"Close",tracksN:"{{n}} tracks",matchedOf:"{{a}} of {{b}} tracks"},disclaimer:{text:"Portfolio project by Gustavo Martins Gripaldi. Static demo: accounts and transfers are simulated and the data stays in your browser.",link:"See it in the portfolio"},nav:{main:"Main",app:"App navigation",homeAria:"ITransferMusic, home page",about:"About",code:"Code",openDemo:"Open demo",dashboard:"Dashboard",transfer:"New transfer",transfers:"Transfers",playlists:"Playlists",syncs:"Syncs",generator:"Playlist generator",connections:"Connections",menu:"Menu",running:"{{n}} transfer(s) running"},footer:{tagline:"Connect your streaming services and take playlists from one to another, track by track. Here, all simulated in the browser.",demo:"Demo",open:"Open the dashboard",project:"Project",by:"Built by {{name}}",inPortfolio:"ITransferMusic in the portfolio",github:"Code on GitHub",marks:"Trademarks belong to their respective owners; portfolio project with no affiliation."},home:{eyebrow:"Portfolio project \xB7 FastAPI + Angular",title1:"Your playlists,",title2:"on any service.",lead:"Transfer, generate and sync playlists across Spotify, YouTube Music, Apple Music, Amazon Music and Deezer. Every track is searched in the destination and you see how confident each match is before running.",cta:"Sign in as demo",how:"How it works",note:"Demo session as {{name}}. No sign-up, no password, nothing leaves the browser.",services:"Supported services",demoSource:"source",demoTarget:"Destination \xB7 Deezer",demoResult:"4 of 5 tracks found \xB7 1 live version",notFound:"not found",howEyebrow:"How it works",howTitle:"From the source library to a ready playlist in the destination",s1t:"Connect the services",s1d:"OAuth2 with each provider. In the demo the consent screen is simulated and says so in big letters.",s2t:"Pick playlists and tracks",s2d:"Several playlists at once, the personal library included, or only the tracks you tick.",s3t:"Check the matches",s3d:"Each track is searched by title and artist in the destination. Live or remastered versions show a lower confidence.",s4t:"Follow the job",s4d:"The transfer runs in the background, track by track, and survives a page reload.",featEyebrow:"Features",featTitle:"The four tools of ITransferMusic",popEyebrow:"Popular conversions",popTitle:"One click and the wizard knows the way",popText:"Each conversion opens the wizard with source and destination already picked. If a service is not connected yet, the simulated OAuth takes two clicks.",to:"to",convert:"Convert",archEyebrow:"Under the hood",archTitle:"The same FastAPI contract, answered in the browser",archText:"The original backend (FastAPI, MongoDB, JWT, OAuth2 with the providers and APScheduler) is still in the repository. In the demo, an interceptor answers the same routes and DTOs with a copy of the service rules, and the database is localStorage.",archCta:"How the demo mirrors the API",archMore:"and more routes, {{n}} in total"},feat:{transfer:{title:"Transfer",text:"Copy whole playlists or chosen tracks from one service to another, with a preview of the matches.",cta:"New transfer"},sync:{title:"Sync",text:"Link the source playlist to its copy in the destination and the scheduler copies new tracks every day or every week.",cta:"See syncs"},share:{title:"Share",text:"Create a public link to a transferred playlist, with the track list and what was found on each service.",cta:"See transfers"},generator:{title:"Generator",text:"Mix genres, moods and a free prompt and get real track suggestions, ready to save on any service.",cta:"Open the generator"}},about:{eyebrow:"About the project",title:"A playlist platform, without a server",lead:"ITransferMusic is a web platform to transfer, generate and sync playlists across streaming services, with a FastAPI + MongoDB backend and an Angular frontend. This published version is a static demo: the frontend talks to the same API, but a copy of it running in your browser answers.",stackTitle:"Stack",v2:"Version 2 (this demo)",v1:"Original version (tag v1-original)",row:{front:"Frontend",back:"Backend",data:"Data",auth:"Authentication",jobs:"Jobs"},v2front:"Angular 21.2 standalone, no zone.js, signals, SSG for public pages, Tailwind CSS 4, Transloco (PT-BR and EN)",v1front:"Angular 19 standalone, Tailwind CSS 3, Transloco",v2back:"The same FastAPI, untouched in BackEnd/; the demo answers in the browser",v1back:"FastAPI + Uvicorn, Pydantic v2, httpx",v2data:"localStorage (demo) or MongoDB (full stack)",v1data:"MongoDB through Motor",v2auth:"Demo JWT, no typed password; simulated OAuth",v1auth:"JWT (python-jose) + bcrypt; OAuth2 with Spotify and Google, tokens encrypted with Fernet",v2jobs:"Transfer job and scheduler replayed against the clock",v1jobs:"FastAPI BackgroundTasks and APScheduler (cron every 15 min)",mirrorTitle:"How the demo mirrors the API",mirrorText:"The app calls exactly the routes of BackEnd/src/api/v1 (base http://localhost:8000/api/v1, the same as the original frontend), with the same DTOs and the same error messages, Pydantic's 422 format included. In the demo build, an HttpClient interceptor answers those calls with a translation of the Python services and stores the data in localStorage.",tableCaption:"FastAPI routes answered by the demo",method:"Method",route:"Route",what:"What it does",diffTitle:"Deliberate differences",diffText:"Mirroring the API surfaced a few real bugs in the original. They were fixed only in the demo (the backend stays untouched) and are commented in the code.",d1k:"scheduler",d1:"A sync set between 23:46 and 23:59 UTC never ran: _is_due builds the scheduled time on today's date, so on the 00:00 tick it lands in the future. The demo uses the latest occurrence before the tick.",d2k:"transfer",d2:"When no track was found (or the source was empty), the original still created an empty playlist in the destination and marked the transfer as failed. The demo creates nothing.",d3k:"generator",d3:"When saving a generated playlist, the original stored matched=true for every track, even the ones it did not find. The demo stores the real result.",d4k:"accounts",d4:"POST /transfers accepted the job even without the source or destination account linked, and it failed later in the background. The demo refuses at once with a 400 and the same message.",d5k:"sync",d5:"POST /syncs/{id}/run answered 202 even for a sync that does not exist. The demo answers 404. PATCH also updates updated_at now.",d6k:"limit",d6:"GET /transfers accepted any limit. The demo clamps it between 1 and 100.",d7k:"extensions",d7:"Routes only the demo has: POST /transfers/preview (the matching without running the job, for the preview step) and GET /__demo/scheduler (the APScheduler job). Each result gets confidence and matched_name. With the real backend, the preview step says it does not exist.",d8k:"providers",d8:"In the original only Spotify and YouTube Music have real OAuth (Apple Music and Amazon Music are stubs, Deezer is out of scope). The demo simulates all five, with a consent screen that says it is simulated.",servicesTitle:"Services and what the original supports",faqTitle:"Frequently asked questions",by:"A project by"},faq:{q1:"How does a transfer work?",q1a:"You pick the source, the destination and the playlists (or tracks). The backend reads each track, searches title and artist in the destination and creates a new playlist with everything it found. The work runs in the background: you can close the page and come back later.",q2:"What happens to tracks that are not found?",q2a:"Matching is a text search. Tracks missing from the destination catalogue, from another region or with different metadata may not show up. The transfer becomes partial (say, 42 of 50) and the full list stays in the history.",q3:"Is my data safe?",q3a:"In the real app, official OAuth only: the services' passwords never go through ITransferMusic and tokens are encrypted with Fernet before reaching the database. This demo has no real account at all: nothing is sent to any provider and the data stays in localStorage.",q4:"Do playlists stay in sync on their own?",q4a:"Only if you create a sync. It links the source playlist to its copy in the destination; the scheduler runs every 15 minutes and, at the chosen time (daily or weekly), copies the new tracks. Mirror mode also removes tracks, when both sides are on the same service.",q5:"What if I delete the playlist in the destination?",q5a:"The /alive endpoint detects it is gone: the history keeps the record with every track and warns that the playlist was removed from the provider.",q6:"Can I see the code?",q6a:"Yes: the repository has the original FastAPI backend and this frontend. The README explains how to run the full stack with MongoDB and your own OAuth credentials."},login:{eyebrow:"Demo session",title:"Sign in and move a few playlists",lead:"The demo account already has Spotify, YouTube Music and Apple Music connected, a transfer history and two syncs. Amazon Music and Deezer are left for you to connect through the simulated OAuth.",p1:"3 services connected, 2 to connect",p2:"5 transfers in the history",p3:"2 scheduled syncs",how:"The button sends POST /auth/login with the public demo account. There is no password field: nothing you type leaves the browser.",howApi:"Full stack mode: the button sends POST /auth/login to FastAPI with the demo account (create it first with POST /auth/register).",failed:"Could not sign in."},consent:{simulated:"SIMULATED consent screen",simulatedText:"This page is part of the demo. No data goes to {{service}}, no password is asked for and nothing leaves your browser. In the real app you would be on the service's official site here.",title:"{{app}} wants to access your {{service}} account",account:"Demo account \xB7 {{service}}",scopes:"Requested permissions",s1:"Read your playlists and library",s2:"Create playlists and add tracks",s3:"See your profile name",allow:"Authorize (simulated)",real:"OAuth2 Authorization Code flow: authorize, consent, redirect with code and state, exchange on the backend.",invalid:"Invalid authorization request."},callback:{linking:"Linking the account...",linked:"{{service}} connected.",denied:"{{service}} authorization cancelled.",failed:"Could not link the account."},dash:{eyebrow:"Dashboard",hello:"Hi, {{name}}!",subtitle:"All set to move your playlists.",newTransfer:"New transfer",stat:{linked:"Linked accounts",transfers:"Transfers",tracks:"Tracks transferred",syncs:"Active syncs"},hintDone:"{{n}} completed or partial",hintTracks:"of {{n}} processed",hintSyncs:"{{n}} in total",running:"Running",myPlaylists:"My transferred playlists",viewAll:"See all",empty:"Your transferred playlists show up here.",linked:"Linked accounts",manage:"Manage",nextSyncs:"Next syncs",generatorText:"Genres, moods and a prompt become a playlist"},conn:{eyebrow:"Connections",title:"Music services",subtitle:"Connect your accounts to move playlists between them. In the demo OAuth is simulated: no credential is asked for and nothing goes to the services.",connected:"Connected",disconnected:"Not connected",connect:"Connect",unlink:"Unlink",as:"Account",userId:"Service ID",since:"Linked on",token:"Token",tokenText:"encrypted on the server, expires {{when}}",connectHint:"Opens the simulated {{service}} consent screen and comes back with the account linked.",unlinked:"{{service}} unlinked.",failed:"Could not finish.",flowTitle:"What happens when you connect",f1:"The app calls GET /auth/oauth/{provider}/authorize and gets the consent URL and a signed state (CSRF protection).",f2:"In the real app you authorize on the service's site. Here, on a simulated screen that asks for nothing.",f3:"The service redirects to /auth/callback/{provider} with code and state; the app POSTs both.",f4:"The backend exchanges the code for tokens, encrypts them with Fernet and stores them in linked_accounts. The demo only stores the simulated account."},pl:{eyebrow:"Libraries",title:"Playlists",subtitle:"The playlists of each connected service. Pick one to see its tracks or take it to another service.",services:"Connected services",list:"Service playlists",search:"Search playlists...",library:"Personal library",empty:"No playlist found.",pick:"Pick a playlist to see its tracks.",transfer:"Transfer this playlist",none:"No service connected yet.",failed:"Could not load the playlists."},wiz:{eyebrow:"New transfer",title:"Move playlists between services",steps:"Steps",stepOf:"Step {{n}} of {{total}}",step:{source:"Source",target:"Destination",pick:"Playlists",preview:"Matches",run:"Confirm"},h:{source:"Which service do the playlists come from?",target:"Which service do they go to?",pick:"Which {{source}} playlists?",preview:"What was found on {{target}}",run:"Names and signature of the new playlists"},isSource:"It is the source",notLinked:"Not connected",selectAll:"Select all",counter:"{{p}} playlists \xB7 {{n}} tracks",personal:"Personal library",playlists:"Playlists",ofTracks:"{{a}} of {{b}} tracks",chooseTracks:"Choose tracks",allTracks:"All tracks",matching:"Searching every track on {{target}}...",noPreview:"This backend has no preview (POST /transfers/preview is a demo extension). The matches show up in the transfer result.",filter:"Filter tracks",f:{all:"All",review:"Review",missing:"Not found"},legend:"High: 90% or more \xB7 Medium: 75% to 89% \xB7 Low: under 75%",found:"{{a}} of {{b}} tracks found on {{target}}",nothing:"Nothing to review here.",name:"Playlist name",description:"Description (optional)",defaultName:"{{name}} (transferred)",watermark:'Apply the "By ITransferMusic" signature (name and description)',finalName:"Final name:",start:"Start the transfer ({{n}})",started:"{{n}} transfer(s) queued.",failed:"Could not start the transfer."},match:{high:"High",medium:"Medium",low:"Low",none:"Not found",found:"Found",as:"as",missingIn:"not on {{service}}",title:"Match confidence (title and artist)"},status:{pending:"Queued",running:"Running",completed:"Completed",partial:"Partial",failed:"Failed",active:"Active",paused:"Paused",error:"Error"},jobs:{progress:"Transfer progress",done:"Transfer finished: {{name}} ({{matched}} of {{total}} tracks).",doneFailed:"Transfer failed: {{name}}."},tr:{eyebrow:"Jobs and history",title:"Transfers",subtitle:"Every transfer runs in the background, track by track. Reloading the page interrupts nothing.",last:"Last track:",history:"History",filter:"Filter history",empty:"No transfers here.",generated:"made with the generator",shared:"shared",from:'From "{{name}}"',deleted:"This playlist was removed from the destination provider. The data below stays in your history.",share:"Share",sync:"Sync",open:"Open in the destination",copy:"Copy",copied:"Link copied.",failed:"Could not share."},share:{eyebrow:"Playlist shared by {{name}}",local:"Static demo: this link only works in the browser where the playlist was transferred.",missing:"Shared playlist not found"},setup:{eyebrow:"New sync",desc:"source \u2192 copy in the destination",frequency:"Frequency",daily:"Daily",weekly:"Weekly",hour:"Hour",minute:"Minute",tz:"In your time zone ({{tz}}). Stored in UTC: {{utc}}.",method:"Method",add_only:"Add only",add_onlyDesc:"Every track added to the source playlist is added to the destination.",mirror:"Mirror",mirrorDesc:"Keeps both playlists the same (only removes when both sides are on the same service).",confirm:"Create sync",created:"Sync created.",failed:"Could not create the sync."},sync:{eyebrow:"Syncs",title:"Mirrored playlists",subtitle:"Keep two playlists on different services up to date. The scheduler checks every 15 minutes which ones are due.",new:"New sync",list:"Syncs",when:"When",last:"Last run",next:"Next",never:"never",nextAt:"next {{when}}",pause:"Pause",resume:"Resume",toggle:"Sync of {{name}} active",paused:"Sync of {{name}} paused.",resumed:"Sync of {{name}} resumed.",runNow:"Run now",ran:"+{{n}} track(s) in {{name}}.",remove:"Remove the sync of {{name}}",removeShort:"Remove",removed:"Sync removed.",empty:"No syncs yet",emptyHint:"After a transfer, link the source playlist to the one created in the destination.",failed:"Could not finish.",schedTitle:"Scheduler",schedNote:'In the demo the "server" only exists while the tab is open: ticks happen every 15 minutes and, when you come back, the missed ones are processed, as if the process had never stopped.',schedNoteApi:"With the real backend, APScheduler runs inside the FastAPI process (scheduler.py).",log:"Recent runs",manual:"manual",noRuns:"No runs yet.",tz:"Your time zone (PATCH /auth/me)",tzSaved:"Time zone saved: {{tz}}.",pickTitle:"Pick a transfer",pickText:"Finished transfers whose playlist still exists in the destination.",pickEmpty:"No transfer available."},gen:{eyebrow:"Generator",title:"Playlist generator",subtitle:"Pick genres, moods and, if you like, a free prompt. Suggestions come from the source service catalogue and can be saved on any connected service.",source:"Search on service",genres:"Genres",moods:"Moods",mood:{Happy:"Happy",Sad:"Sad",Angry:"Angry",Relaxed:"Relaxed",Energetic:"Energetic",Romantic:"Romantic"},prompt:"Prompt (optional)",promptHint:"E.g. brazilian rock, rain, piano to study",count:"How many tracks",generate:"Generate",regenerate:"Generate again",more:"Generate more",results:"Suggestions ({{n}})",queries:"Queries used:",remove:"Remove {{name}}",emptyHint:"Pick genres and moods and click Generate.",noMore:"No new tracks for these filters.",saveTitle:"Save as a playlist",target:"Save on service",save:"Save on {{service}}",saved:"{{a}} of {{b}} tracks found on {{service}}. Playlist created.",failed:"Could not generate."},nf:{eyebrow:"Error 404",title:"That track is not in the catalogue",text:"The page you looked for does not exist. Go back home or open the dashboard.",home:"Go home"}};export{e as EN};
